    'Cash',
    'The money sitting in the accounts you have added, after every transaction recorded against them. Not physical notes — anything you could spend today.',
  ),
  'investments': HelpEntry(
    'Investments',
    'What your holdings are worth right now, at the latest price the app has. This moves with the market even when you do nothing.',
  ),
  'invested': HelpEntry(
    'Invested (cost basis)',
    'What you actually paid for your holdings, added up. It does not change when prices move — only when you buy or sell.',
  ),
  'unrealisedPnl': HelpEntry(
    'Unrealised profit & loss',
    'What your holdings are worth now, minus what you paid for them. "Unrealised" means on paper: you have not sold, so nothing has been gained or lost yet and no tax is due.',
  ),
  'savingsRate': HelpEntry(
    'Savings rate',
    'The share of your income you did not spend this period. Saving 30% of what comes in is a common target, but the number that matters is whether it is rising.',
  ),
  'liabilities': HelpEntry(
    'Liabilities',
    'What you owe — loans, credit-card balances, anything with a principal outstanding. Subtracted from what you own to give net worth.',
  ),
